import CustomButton from './CustomButton'
import { keyboardLayout as defaultLayout } from '@/lib/KeyboardLayout'
import { cn } from '@/lib/utils'

export interface KeyboardKey {
    label?: string
    subLabel?: string
    icon?: React.ReactNode
    wide?: boolean
    space?: boolean
}

export interface KeyboardProps {
    layout?: KeyboardKey[][]
    className?: string
    theme?: 'dark' | 'light'
}

const Keyboard = ({
    layout = defaultLayout,
    className,
    theme = 'dark'
}: KeyboardProps) => {
    const themeClasses = theme === 'dark'
        ? 'bg-neutral-900'
        : 'bg-gray-100'

    return (
        <div className={cn("p-4 rounded-lg shadow-2xl lg:max-w-5xl max-w-2xl mx-auto", themeClasses, className)}>
            {layout.map((row, rowIndex) => (
                <div key={rowIndex} className="flex justify-center">
                    {row.map((key, keyIndex) => (
                        <CustomButton
                            key={keyIndex}
                            label={key.label}
                            subLabel={key.subLabel}
                            icon={key.icon}
                            wide={key.wide}
                            space={key.space}
                        />
                    ))}
                </div>
            ))}
        </div>
    )
}

export default Keyboard

import React from 'react'

type KeyButtonProps = {
    label?: string;
    subLabel?: string;
    icon?: React.ReactNode;
    wide?: boolean;
    space?: boolean;
};


const CustomButton = ({ label, subLabel, icon, wide, space }: KeyButtonProps) => {


    return (
        <button
            className={`flex flex-col hover:scale-108 transition-transform duration-200 ease-in-out items-center justify-center rounded-md border cursor-pointer border-gray-900 text-white p-2 m-0.5 
            shadow-lg shadow-neutral-100/50 active:scale-95 active:shadow-inner

        ${space ? 'w-[900px]' : wide ? 'w-[150px]' : 'w-20'} h-12 bg-black`}
        >
            {icon ? icon : (
                <>
                    {subLabel && <span className="text-sm text-center text-gray-400">{subLabel}</span>}
                    <span className="w-fit text-center text-sm">{label}</span>
                </>
            )}
        </button>
    )
}


export default CustomButton

export const keyboardLayout = [
    [
        { label: 'esc' }, { label: 'F1', subLabel: '☀' }, { label: 'F2', subLabel: '⛭' }, { label: 'F3', subLabel: '☐' },
        { label: 'F4', subLabel: '🔍︎' },
        { label: 'F5', subLabel: '🎙️' },
        { label: 'F6', subLabel: '⏾' },
        { label: 'F7', subLabel: '⏮' },
        { label: 'F8', subLabel: '▶' },
        { label: 'F9', subLabel: '⏭' },
        { label: 'F10', subLabel: "🔇" },
        { label: 'F11', subLabel: '🔈' },
        { label: 'F12', subLabel: "🔊" },
        { label: '⚫' }
    ],
    [
        { label: '`', subLabel: '~' }, { label: '1', subLabel: '!' }, { label: '2', subLabel: '@' }, { label: '3', subLabel: '#' }, { label: '4', subLabel: '$' },
        { label: '5', subLabel: '%' }, { label: '6', subLabel: '^' }, { label: '7', subLabel: '&' }, { label: '8', subLabel: '*' },

        { label: '9', subLabel: '(' }, { label: '0', subLabel: ')' }, { label: '-', subLabel: '_' }, { label: '=', subLabel: '+' }, { label: 'delete', wide: true }
    ],
    [
        { label: 'tab', wide: true }, { label: 'Q' }, { label: 'W' }, { label: 'E' }, { label: 'R' }, { label: 'T' }, { label: 'Y' }, { label: 'U' }, { label: 'I' }, { label: 'O' }, { label: 'P' }, { label: '[', subLabel: '{' }, { label: ']', subLabel: '}' }, { label: '\\', subLabel: '|' }
    ],
    [
        { label: 'capslock', wide: true }, { label: 'A' }, { label: 'S' }, { label: 'D' }, { label: 'F' }, { label: 'G' }, { label: 'H' }, { label: 'J' }, { label: 'K' }, { label: 'L' }, { label: ';', subLabel: ':' }, { label: "'", subLabel: '"' }, { label: 'return', wide: true }
    ],
    [
        { label: 'shift', wide: true }, { label: 'Z' }, { label: 'X' }, { label: 'C' }, { label: 'V' }, { label: 'B' }, { label: 'N' }, { label: 'M' }, { label: ',', subLabel: '<' }, { label: '.', subLabel: '>' }, { label: '/', subLabel: '?' }, { label: 'shift', wide: true }
    ],
    [
        { label: 'fn', subLabel: ' 🌍︎ ' }, { label: 'control', subLabel: '^', }, { label: 'option', subLabel: '⌥' }, { label: 'command', subLabel: '⌘' }, { label: 'space', wide: true }, { label: 'command', subLabel: '⌘' },
        { label: 'option', subLabel: '⌥' },

        { label: '←' }, { label: '↑' }, { label: '↓' }, { label: '→' }

    ]
];
